{
    size_t len;
    unsigned char *q = *p;

    if( ( q + 2 ) > end )
        return( MBEDTLS_ERR_SSL_BAD_RECORD );

    len = ( q[0] << 8 ) | q[1];
    q += 2;

    if( ( q + len ) > end )
