int mbedtls_ssl_read_psk_hint(mbedtls_ssl_context *ssl, unsigned char **p, unsigned char *end)
{
    size_t len;

    if ((end - *p) < 2) {
        return MBEDTLS_ERR_SSL_BAD_HS_CLIENT_KEY_EXCHANGE;
    }

    len = (size_t)(((*p)[0] << 8) | (*p)[1]);
    *p += 2;

    if (len > (size_t)(end - *p)) {
        return MBEDTLS_ERR_SSL_BAD_HS_CLIENT_KEY_EXCHANGE;
    }

    /* Ignore the actual hint as only one PSK is supported */
    *p += len;

    return 0;
}

